/* Fix round 4: n, m, r, x, z, ñ and the accented vowels are drawn with control points, not the Hershey data.
   Arches (n, m) are the school «puente»: the lead-in rises from the baseline to the x-height and falls back,
   so n has two downstrokes in total and m three. */

/** A smooth centreline through control points (flat [x, y, x, y, …]), resampled about every 1.5 units. */
function spline(flat: number[], step = 1.5): ModelStroke {
  const P: ModelPoint[] = []
  for (let i = 0; i < flat.length; i += 2) P.push({ x: flat[i], y: flat[i + 1] })
  const out: ModelPoint[] = [P[0]]
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(P.length - 1, i + 2)]
    const n = Math.max(1, Math.ceil(Math.hypot(p2.x - p1.x, p2.y - p1.y) / step))
    for (let k = 1; k <= n; k++) {
      const t = k / n
      const cr = (a: number, b: number, c: number, d: number) =>
        0.5 * (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t * t + (-a + 3 * b - 3 * c + d) * t * t * t)
      out.push({ x: cr(p0.x, p1.x, p2.x, p3.x), y: cr(p0.y, p1.y, p2.y, p3.y) })
    }
  }
  return out.map((p) => ({ x: round1(p.x), y: round1(p.y) }))
}

/** `count` arches from x0, each `w` wide: rising from the baseline to the x-height and back. The first is the lead-in. */

/** One wave (virgulilla) from x0 to x1, centred on yc. */

/** A letter with marks added in its own frame. `dropDots` removes the base's own dot (í takes the accent instead). */

/** Acute accent above the x-height, rising to the right, centred on cx. */
